// nppiSum / nppiMean / nppiMean_StdDev family executor.
//
// Host-visible surface (safe for plain .cpp translation units): the entry-point
// templates are declared here and defined + explicitly instantiated in
// nppi_statistics_executor.cu.  The public wrappers are generated by
// mpp_scripts/gen_family.py (mpp_scripts/families/nppi_{sum,mean,mean_stddev}.json).
//
// Semantics (baseline NVIDIA NPP 13.4, validated by differential tests):
//   * 2D ROI sum / mean / (mean, std-dev) reduction, device scalar or per
//     channel array output (C3/C4/AC4), optional binary mask.
//   * Sum : out = per-channel sum.  8u64s accumulates into Npp64s.
//   * Mean: out = sum / pixel_count (valid-pixel count when masked).
//   * Mean_StdDev: mean and (population) standard deviation of each selected
//     channel.  Integral sources accumulate in double precision.
//   * AC4 (AlphaPreserve=true) reduces the first three channels and leaves the
//     alpha (4th) channel out of the result.
//   * Masked C1MR reduces a single channel; masked C3CMR reduces one channel
//     selected by nCOI (0-based).  Mask byte != 0 means "valid".
//   * pDeviceBuffer is scratch only; the buffer-size helpers report a size
//     sufficient for the corresponding reduction (exact bytes are not a
//     contract).
#ifndef NPPI_STATISTICS_EXECUTOR_H
#define NPPI_STATISTICS_EXECUTOR_H

#include "npp.h"

namespace nppi {
namespace statistics {

// ---------------------------------------------------------------------------
// Sum
// ---------------------------------------------------------------------------

// out = per-channel sum of the ROI.  Channels = packed channels per pixel,
// AlphaPreserve selects AC4 (reduces Channels-1, output holds those values).
template <typename D, int Channels, typename Acc, bool AlphaPreserve>
NppStatus runSum(const D *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, Acc *pSum,
                 cudaStream_t stream);

// ---------------------------------------------------------------------------
// Mean
// ---------------------------------------------------------------------------

// out = per-channel mean of the ROI.
template <typename DType, int Channels, bool AlphaPreserve>
NppStatus runMean(const DType *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, Npp64f *pMean,
                  cudaStream_t stream);

// Single-channel mean with a mask (C1MR).
template <typename DType>
NppStatus runMeanMasked(const DType *pSrc, int nSrcStep, const Npp8u *pMask, int nMaskStep, NppiSize oSizeROI,
                        Npp8u *pDeviceBuffer, Npp64f *pMean, cudaStream_t stream);

// Three-channel mean restricted to one channel by nCOI, with a mask (C3CMR).
template <typename DType>
NppStatus runMeanMaskedCoi(const DType *pSrc, int nSrcStep, const Npp8u *pMask, int nMaskStep, NppiSize oSizeROI,
                           int nCOI, Npp8u *pDeviceBuffer, Npp64f *pMean, cudaStream_t stream);

// ---------------------------------------------------------------------------
// Mean + StdDev
// ---------------------------------------------------------------------------

// Single-channel mean & std-dev of the ROI (C1R).
template <typename DType>
NppStatus runMeanStdDev(const DType *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, Npp64f *pMean,
                        Npp64f *pStdDev, cudaStream_t stream);

// Three-channel mean & std-dev of one selected channel (C3CR).
template <typename DType>
NppStatus runMeanStdDevCoi(const DType *pSrc, int nSrcStep, NppiSize oSizeROI, int nCOI, Npp8u *pDeviceBuffer,
                           Npp64f *pMean, Npp64f *pStdDev, cudaStream_t stream);

// Single-channel mean & std-dev with a mask (C1MR).
template <typename DType>
NppStatus runMeanStdDevMasked(const DType *pSrc, int nSrcStep, const Npp8u *pMask, int nMaskStep, NppiSize oSizeROI,
                              Npp8u *pDeviceBuffer, Npp64f *pMean, Npp64f *pStdDev, cudaStream_t stream);

// Three-channel mean & std-dev of one selected channel with a mask (C3CMR).
template <typename DType>
NppStatus runMeanStdDevMaskedCoi(const DType *pSrc, int nSrcStep, const Npp8u *pMask, int nMaskStep, NppiSize oSizeROI,
                                 int nCOI, Npp8u *pDeviceBuffer, Npp64f *pMean, Npp64f *pStdDev, cudaStream_t stream);

// ---------------------------------------------------------------------------
// Min / Max / MinMax
// ---------------------------------------------------------------------------

// out = per-channel minimum of the ROI.  Channels = packed channels per pixel;
// AlphaPreserve selects AC4 (reduces Channels-1, output holds those values).
template <typename D, int Channels, bool AlphaPreserve>
NppStatus runMin(const D *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, D *pMin,
                 cudaStream_t stream);

// out = per-channel maximum of the ROI.
template <typename D, int Channels, bool AlphaPreserve>
NppStatus runMax(const D *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, D *pMax,
                 cudaStream_t stream);

// out = per-channel (min, max) pair of the ROI.
template <typename D, int Channels, bool AlphaPreserve>
NppStatus runMinMax(const D *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, D *pMin, D *pMax,
                    cudaStream_t stream);

// ---------------------------------------------------------------------------
// MinIndx / MaxIndx (per-channel extreme value + its pixel coordinate).
// ---------------------------------------------------------------------------

// out = per-channel minimum (IsMin=true) or maximum (IsMin=false) of the ROI
// together with the (x, y) coordinate of the first (in row-major scan order)
// pixel holding that extreme.  Channels = packed channels per pixel;
// AlphaPreserve selects AC4 (reduces Channels-1, output holds those values).
// pValue / pIndexX / pIndexY each hold readCh elements on device.
template <typename D, int Channels, bool AlphaPreserve, bool IsMin>
NppStatus runExtrIndx(const D *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, D *pValue, int *pIndexX,
                      int *pIndexY, cudaStream_t stream);

// ---------------------------------------------------------------------------
// MinMaxIndx (single selected channel -> scalar min/max + NppiPoint positions)
// ---------------------------------------------------------------------------

// Single-channel min & max with the position of each.  pMask may be null (then
// nMaskStep is unused); nCOI is 1-based and only meaningful for 3-channel
// inputs (Channels=3 selects channel nCOI-1).  All outputs are single scalars /
// single NppiPoint on device.
template <typename D, int Channels>
NppStatus runMinMaxIndx(const D *pSrc, int nSrcStep, const Npp8u *pMask, int nMaskStep, NppiSize oSizeROI, int nCOI,
                        D *pMinValue, D *pMaxValue, NppiPoint *pMinIndex, NppiPoint *pMaxIndex, Npp8u *pDeviceBuffer,
                        cudaStream_t stream);

// ---------------------------------------------------------------------------
// Norm / NormDiff (L1 / L2 / Inf)
// ---------------------------------------------------------------------------

// 2D ROI norm family.  L1 = sum |a|, L2 = sqrt(sum a^2), Inf = max |a|.
// NormDiff reduces over |pSrc1 - pSrc2| instead of pSrc alone.
enum class NormType { L1, L2, Inf };

// out = per-channel norm of the ROI.  Channels = packed channels per pixel,
// AlphaPreserve selects AC4 (reduces Channels-1, output holds those values).
template <NormType NT, typename D, int Channels, bool AlphaPreserve>
NppStatus runNorm(const D *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, Npp64f *pNorm,
                  cudaStream_t stream);

// NormDiff: out = per-channel norm of (pSrc1 - pSrc2).
template <NormType NT, typename D, int Channels, bool AlphaPreserve>
NppStatus runNormDiff(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, NppiSize oSizeROI,
                      Npp8u *pDeviceBuffer, Npp64f *pNorm, cudaStream_t stream);

// Single-channel norm with a mask (C1MR).
template <NormType NT, typename D>
NppStatus runNormMasked(const D *pSrc, int nSrcStep, const Npp8u *pMask, int nMaskStep, NppiSize oSizeROI,
                        Npp8u *pDeviceBuffer, Npp64f *pNorm, cudaStream_t stream);

// Three-channel norm restricted to one channel by nCOI, with a mask (C3CMR).
template <NormType NT, typename D>
NppStatus runNormMaskedCoi(const D *pSrc, int nSrcStep, const Npp8u *pMask, int nMaskStep, NppiSize oSizeROI,
                           int nCOI, Npp8u *pDeviceBuffer, Npp64f *pNorm, cudaStream_t stream);

// Two-source (Sep1 - Sep2) masked single channel (C1MR).
template <NormType NT, typename D>
NppStatus runNormDiffMasked(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, const Npp8u *pMask,
                            int nMaskStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, Npp64f *pNorm,
                            cudaStream_t stream);

// Two-source masked three-channel, one channel selected by nCOI (C3CMR).
template <NormType NT, typename D>
NppStatus runNormDiffMaskedCoi(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, const Npp8u *pMask,
                               int nMaskStep, NppiSize oSizeROI, int nCOI, Npp8u *pDeviceBuffer, Npp64f *pNorm,
                               cudaStream_t stream);

// ---------------------------------------------------------------------------
// NormRel (L1 / L2 / Inf): relative error norm between two images.
//   NormRel = norm(pSrc1 - pSrc2) / norm(pSrc2)   (per channel).
// ---------------------------------------------------------------------------

// out = per-channel ratio of the norm of (pSrc1 - pSrc2) to the norm of pSrc2.
template <NormType NT, typename D, int Channels, bool AlphaPreserve>
NppStatus runNormRel(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, NppiSize oSizeROI,
                     Npp8u *pDeviceBuffer, Npp64f *pNorm, cudaStream_t stream);

// Single-channel NormRel with a mask (C1MR).  Both numerator and denominator
// are reduced over the valid (mask != 0) pixels only.
template <NormType NT, typename D>
NppStatus runNormRelMasked(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, const Npp8u *pMask,
                           int nMaskStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, Npp64f *pNorm,
                           cudaStream_t stream);

// Three-channel NormRel restricted to one channel by nCOI, with a mask (C3CMR).
template <NormType NT, typename D>
NppStatus runNormRelMaskedCoi(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, const Npp8u *pMask,
                              int nMaskStep, NppiSize oSizeROI, int nCOI, Npp8u *pDeviceBuffer, Npp64f *pNorm,
                              cudaStream_t stream);

// ---------------------------------------------------------------------------
// DotProd: out = sum over the ROI of pSrc1 * pSrc2 (per channel, Npp64f).
// ---------------------------------------------------------------------------
// Channels = packed channels per pixel; AlphaPreserve selects AC4 (reduces
// Channels-1, output holds those values).  A single scalar (C1R) or a per
// channel array (C3/C4/AC4) is written to *pDp.
template <typename D, int Channels, bool AlphaPreserve>
NppStatus runDotProd(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, NppiSize oSizeROI,
                     Npp8u *pDeviceBuffer, Npp64f *pDp, cudaStream_t stream);

NppStatus sumGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus meanGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus meanStdDevGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus minGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus maxGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus minMaxGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus minIndxGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus maxIndxGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus minMaxIndxGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);

NppStatus normL1GetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus normL2GetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus normInfGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus normDiffL1GetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus normDiffL2GetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus normDiffInfGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus normRelL1GetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus normRelL2GetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus normRelInfGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus dotProdGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus fullNormLevelGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus sameNormLevelGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus validNormLevelGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);

// ---------------------------------------------------------------------------
// AverageError / AverageRelativeError (package p1.3c)
// ---------------------------------------------------------------------------

// out = 1 / (W * H * Channels) * sum |pSrc1 - pSrc2| over the ROI; complex
// elements contribute their complex modulus.  Single device Npp64f output.
//
// 5090-measured contract (NVIDIA NPP 13.4, differential tests + probes),
// check order included:
//   * null source                     -> NPP_NULL_POINTER_ERROR (first)
//   * negative ROI                    -> NPP_SIZE_ERROR (before the empty no-op)
//   * zero-sized ROI                  -> NPP_NO_ERROR, nothing written
//   * per source, in order: (uint32)step < row bytes -> NPP_STEP_ERROR;
//     (uint32)step % (sizeof(D) * 2^v2(Channels)) != 0
//                                    -> NPP_NOT_EVEN_STEP_ERROR
//   * null out / null scratch         -> NPP_NULL_POINTER_ERROR (last)
template <typename D, int Channels>
NppStatus runAverageError(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, NppiSize oSizeROI,
                          Npp8u *pDeviceBuffer, Npp64f *pError, cudaStream_t stream);

// out = 1 / (W * H * Channels) * sum |pSrc1 - pSrc2| / max(|pSrc1|, |pSrc2|).
// Pixels with max(|pSrc1|, |pSrc2|) == 0 contribute 0 but stay in the
// normalization (5090-measured: 2x1 mixed probe -> 0.5, all-zero image -> 0.0).
// Validation is identical to runAverageError.
template <typename D, int Channels>
NppStatus runAverageRelativeError(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, NppiSize oSizeROI,
                                  Npp8u *pDeviceBuffer, Npp64f *pError, cudaStream_t stream);

// Scratch-size helpers.  Unlike the other statistics helpers a zero-sized ROI
// returns NPP_NO_ERROR (5090-measured).  Exact bytes are not a contract, only
// that the returned size is sufficient for the matching reduction.
NppStatus averageErrorGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus averageRelativeErrorGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);

// ---------------------------------------------------------------------------
// MaximumError / MaximumRelativeError (package p1.3d)
// ---------------------------------------------------------------------------

// out = max over all ROI samples of |pSrc1 - pSrc2|; complex elements
// contribute their complex modulus.  Single device Npp64f output for every
// channel layout C1..C4 (5090-measured: the NPP documentation claiming a
// per-channel C3/C4 array is wrong; only the first double is written).
//
// 5090-measured contract (NVIDIA NPP 13.4, differential tests + probes),
// check order included:
//   * null source                     -> NPP_NULL_POINTER_ERROR (first)
//   * negative ROI                    -> NPP_SIZE_ERROR (before the empty no-op)
//   * zero-sized ROI                  -> NPP_NO_ERROR, nothing written
//   * per source, in order: (uint32)step < row bytes -> NPP_STEP_ERROR;
//     (uint32)step % (sizeof(D) * 2^v2(Channels)) != 0
//                                    -> NPP_NOT_EVEN_STEP_ERROR
//   * null out / null scratch         -> NPP_NULL_POINTER_ERROR (last)
template <typename D, int Channels>
NppStatus runMaxError(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, NppiSize oSizeROI,
                      Npp8u *pDeviceBuffer, Npp64f *pError, cudaStream_t stream);

// out = max over all ROI samples of |pSrc1 - pSrc2| / max(|pSrc1|, |pSrc2|).
// Samples with max(|pSrc1|, |pSrc2|) == 0 contribute 0, so an all-zero image
// yields 0.0 (5090-measured).  Validation is identical to runMaxError.
template <typename D, int Channels>
NppStatus runMaxRelativeError(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, NppiSize oSizeROI,
                              Npp8u *pDeviceBuffer, Npp64f *pError, cudaStream_t stream);

// Scratch-size helpers.  Like the AverageError helpers (and unlike the other
// statistics helpers) a zero-sized ROI returns NPP_NO_ERROR (5090-measured).
// Exact bytes are not a contract, only that the returned size is sufficient
// for the matching reduction.
NppStatus maximumErrorGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus maximumRelativeErrorGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);

}  // namespace statistics
}  // namespace nppi

#endif  // NPPI_STATISTICS_EXECUTOR_H
